// GENERATED by tooling/arcs/jp_join_pairing/jp_author/r4/gen_gate4.py from the
// round-3 closure review's new shapes (jp_review_r3/: t1, f1, t5), the round-4
// predicate-shape census (b3/*) and the round-4 star and derived-table
// variants (v/*), against live PostgreSQL 17.11. Edit the generator, not this
// file.

import (
	"context"
	"strings"
	"testing"
	"time"
)

// A ROUTED CELL IS RIGHT ONLY WHEN THE SINGLE-PROCESS ANSWER IS POSTGRESQL'S —
// arc JP round 4.
//
// Routing a correlated LATERAL to the coordinator-local pipeline
// (dagplan/lateral_identity_guard.go) makes the DAG arms agree with the
// single-process arm; it does not make either of them right. Round 3's gate
// counted agreement, and three routed cells answered the single-process
// pipeline's wrong rows on every arm (`d/b6starBare`, `d/b6starBareQs`,
// `b/betweenCollide`). Here every cell answers PostgreSQL's rows on five
// arms or refuses where the tip refuses (jp4Loud: a refusal that starts
// answering fails), the pinned residuals are listed (jp4Pins: a pin that
// starts agreeing fails), every ROUTED cell's single-process answer is
// asserted against PostgreSQL's by name, the routing decision is recorded
// for every cell (user names in the `__` space included: only the planner's
// reserved families are minted, plansql.ReservedSlotFamily), and the
// routed-and-right / routed-and-wrong counts are logged.

type jp4Cell struct{ name, sql string }

func TestArcJP4RoutedLateralIsRightOnlyWhenSingleIsRight(t *testing.T) {
	if testing.Short() {
		t.Skip("-short: five arms over the arc JP round-4 corpus")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 40*time.Minute)
	t.Cleanup(cancel)
	single := tmdStandalone(t, ctx)
	spilled := na2Standalone(t, ctx, 512*1024)
	coord := func(opts ...func(*Config)) *Coordinator {
		infra := tmdInfra(t, ctx)
		tmdWriteTables(t, ctx, infra, nil)
		return tmdCoordinator(t, ctx, infra, opts...)
	}
	dag := coord()
	shuffled := coord(func(c *Config) { c.BroadcastBytesOverride = 1 })
	fast := coord(func(c *Config) { c.LocalFastPathBytes = DefaultLocalFastPathBytes })
	routes := func(c *Coordinator) int64 {
		var n int64
		for _, v := range a2fReadRoutes(c).values {
			n += v
		}
		return n + c.WindowOverLateralLocalRoutes() + c.PolicedWindowLocalRoutes() + c.ResidualSidesLocalRoutes()
	}
	type arm struct {
		name  string
		run   func(string) string
		coord *Coordinator
	}
	arms := []arm{
		{"single", func(s string) string { return r1Single(ctx, single, s) }, nil},
		{"spilled512k", func(s string) string { return r1Single(ctx, spilled, s) }, nil},
		{"dag", func(s string) string { return r1DAG(ctx, dag, s) }, dag},
		{"dag-shuffled", func(s string) string { return r1DAG(ctx, shuffled, s) }, shuffled},
		{"fastpath", func(s string) string { return r1DAG(ctx, fast, s) }, nil},
	}
	routedRight, routedWrong, routedLoud := 0, 0, 0
	for _, tc := range jp4Cells {
		w, ok := jp4Postgres[tc.name]
		if !ok {
			t.Fatalf("%s: no PostgreSQL row set recorded", tc.name)
		}
		t.Run(tc.name, func(t *testing.T) {
			for _, a := range arms {
				var before int64
				if a.coord != nil {
					before = routes(a.coord)
				}
				got := a.run(tc.sql)
				if a.coord != nil {
					if moved := routes(a.coord) > before; moved != jp4Routed[tc.name] {
						t.Errorf("%s\n  arm  %s\n  routed single-process: %v, recorded: %v",
							tc.sql, a.name, moved, jp4Routed[tc.name])
					}
				}
				// THE ROUTED CELL'S OWN ASSERTION: routing hands the DAG arms
				// the single-process answer, so that answer is what must be
				// PostgreSQL's.
				if a.name == "single" && jp4Routed[tc.name] && !strings.HasPrefix(w, "ERR ") {
					switch {
					case got == w:
						routedRight++
					case strings.HasPrefix(got, "ERR "):
						routedLoud++
					default:
						// A pinned single-process wrong answer is a FILED
						// residual (the round-4 N1 candidate: a subquery whose
						// FROM holds a LATERAL loses its correlation, every
						// arm, base = tip); it is counted and named, and its
						// pin fails the moment it starts agreeing. Any other
						// routed wrong answer fails here.
						routedWrong++
						if _, pinned := jp4Pins[tc.name+"\x00single"]; pinned {
							t.Logf("routed onto a FILED single-process wrong answer (jp4Pins): %s", tc.name)
						} else {
							t.Errorf("%s\n  ROUTED, and the single-process answer it routes to is wrong\n  got  %s\n  want %s (PostgreSQL 17.11)", tc.sql, got, w)
						}
					}
				}
				key := tc.name + "\x00" + a.name
				if strings.HasPrefix(w, "ERR ") {
					if pin, pinned := jp4Pins[key]; pinned {
						if strings.HasPrefix(got, "ERR ") {
							t.Errorf("%s\n  arm  %s\n  refuses as PostgreSQL does now: delete its jp4Pins entry", tc.sql, a.name)
						} else if got != pin {
							t.Errorf("%s\n  arm  %s\n  got  %s\n  pinned %s (PostgreSQL rejects it: %s)", tc.sql, a.name, got, pin, w)
						}
						continue
					}
					if !strings.HasPrefix(got, "ERR ") {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  PostgreSQL rejects it: %s", tc.sql, a.name, got, w)
					}
					continue
				}
				if pin, pinned := jp4Pins[key]; pinned {
					if got == w {
						t.Errorf("%s\n  arm  %s\n  answers PostgreSQL's %s now: delete its jp4Pins entry", tc.sql, a.name, w)
					} else if got != pin {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  pinned %s (PostgreSQL answers %s)", tc.sql, a.name, got, pin, w)
					}
					continue
				}
				if class, isLoud := jp4Loud[key]; isLoud {
					if got == w {
						t.Errorf("%s\n  arm  %s\n  answers PostgreSQL's %s now: delete its jp4Loud entry", tc.sql, a.name, w)
					} else if !strings.HasPrefix(got, "ERR ") || !strings.Contains(got, class) {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  must refuse with %q (PostgreSQL answers %s)", tc.sql, a.name, got, class, w)
					}
					continue
				}
				if a.name == "spilled512k" && strings.HasPrefix(got, "ERR ") &&
					(strings.Contains(got, "memory budget") || strings.Contains(got, "cross join")) {
					continue // the 512 KiB budget's documented loud refusal
				}
				if got != w {
					t.Errorf("%s\n  arm  %s\n  got  %s\n  want %s (PostgreSQL 17.11)", tc.sql, a.name, got, w)
				}
			}
		})
	}
	t.Logf("routed cells: %d right, %d wrong (every one a filed jp4Pins residual), %d refused (of %d cells)", routedRight, routedWrong, routedLoud, len(jp4Cells))
}

